fn filter_vowels_array(xs: &[char]) -> Vec<char> {
    // Pre-allocate a vector with the same capacity as the input slice,
    // since in the worst case every character could be a vowel.
    let mut ys: Vec<char> = Vec::with_capacity(xs.len());

    // Iterate through each character in the input slice
    for &c in xs {
        // If it's one of the lowercase English vowels, push it to ys
        if matches!(c, 'a' | 'e' | 'i' | 'o' | 'u') {
            ys.push(c);
        }
    }

    ys
}

// Example usage and simple test
fn main() {
    let input: Vec<char> = "Hello, Rustaceans!".chars().collect();
    let filtered = filter_vowels_array(&input);
    assert_eq!(filtered, vec!['e', 'o', 'u', 'a', 'e', 'a']);
    println!("Filtered vowels: {:?}", filtered);
}